import { useNavigate } from "react-router-dom";
import { useState } from "react";

const RoleSelection = () => {
  const navigate = useNavigate();
  const [selectedRole, setSelectedRole] = useState(null);

  const handleProceed = () => {
    if (selectedRole === "student") {
      navigate("/dashboard");
    }
    // later add teacher/others here
  };

  return (
    <div className="flex flex-col items-center justify-center h-screen">
      <h2 className="text-2xl font-semibold mb-4">Select Your Role</h2>
      <div className="space-x-4">
        <button
          className={`px-6 py-2 rounded-xl border ${
            selectedRole === "student" ? "bg-blue-500 text-white" : "bg-gray-100"
          }`}
          onClick={() => setSelectedRole("student")}
        >
          Student
        </button>
      </div>
      <button
        onClick={handleProceed}
        className="mt-6 bg-green-500 text-white px-6 py-2 rounded-xl"
      >
        Proceed
      </button>
    </div>
  );
};

export default RoleSelection;
